#!/usr/bin/env bash
set -euo pipefail
# src-tauri/gen/android is regenerated by `cargo tauri android init --ci` and is
# gitignored, so the edge-to-edge MainActivity is kept here and re-applied after
# init. It forwards system-bar insets (status bar, cutout, gesture bar) to the
# WebView via padding so header buttons stay tappable on edge-to-edge Android.
SRC="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/android/MainActivity.kt"
DST="src-tauri/gen/android/app/src/main/java/com/just2512/fundbollledger/MainActivity.kt"
if [ ! -f "$DST" ]; then
  echo "Android project not initialized — run 'cargo tauri android init --ci' first." >&2
  exit 1
fi
cp "$SRC" "$DST"
echo "Applied edge-to-edge system-bar inset handling to MainActivity.kt"